CREATE TABLE product_images (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),product_id UUID NOT NULL REFERENCES products(id),object_key VARCHAR(500) NOT NULL,alt_text VARCHAR(255),sort_order INTEGER NOT NULL DEFAULT 0,primary_image BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX uq_product_primary_image ON product_images(product_id) WHERE primary_image;
CREATE INDEX idx_product_images_tenant_product ON product_images(tenant_id,product_id);
CREATE TABLE inventory_movements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),branch_id UUID REFERENCES branches(id),product_id UUID REFERENCES products(id),variant_id UUID REFERENCES product_variants(id),movement_type VARCHAR(30) NOT NULL,quantity NUMERIC(12,3) NOT NULL,previous_quantity NUMERIC(12,3),resulting_quantity NUMERIC(12,3),reference_type VARCHAR(50),reference_id UUID,notes VARCHAR(255),created_by UUID REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK((product_id IS NULL)<>(variant_id IS NULL)),CHECK(movement_type IN ('INITIAL','INCREASE','DECREASE','ADJUSTMENT','SALE','RETURN','CANCELLATION')));
CREATE INDEX idx_inventory_tenant_created ON inventory_movements(tenant_id,created_at DESC);
CREATE INDEX idx_inventory_product ON inventory_movements(product_id);
